def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg)
    frame = max(objs, key=lambda o: o["size"])
    y0, x0, y1, x1 = frame["box"]
    fc = frame["colour"]
    out = crop(g, y0, x0, y1, x1).copy()
    emit(out, "Crop the large frame object; its holes are still empty.")

    shapes = []
    for o in objs:
        if o is frame:
            continue
        m = (o["grid"] != bg).astype(int)
        shapes.append((m, o["colour"]))

    def variants(m):
        vs = []
        for k in range(4):
            r = np.rot90(m, k)
            vs.append(r)
            vs.append(np.fliplr(r))
        return vs

    holes = components(out != fc)
    for cells in holes:
        hy0, hx0, hy1, hx1 = bbox(cells)
        hm = np.zeros((hy1 - hy0 + 1, hx1 - hx0 + 1), int)
        for (y, x) in cells:
            hm[y - hy0, x - hx0] = 1
        col = None
        for m, c in shapes:
            if m.shape == hm.shape and np.array_equal(m, hm):
                col = c
                break
        if col is None:
            for m, c in shapes:
                if any(v.shape == hm.shape and np.array_equal(v, hm) for v in variants(m)):
                    col = c
                    break
        if col is None:
            continue
        for (y, x) in cells:
            out[y, x] = col
        emit(out, f"Fill the hole at rows {hy0}-{hy1} with colour {col}, the shape that matches its silhouette.")

    emit(out, "All holes filled: final output.")
    return out
